    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<string> e(n);
    for (int i = 0; i < n; i++) cin >> e[i];

    unordered_set<string> unique;
    for (int i = 0; i < n; i++) {
        size_t at = e[i].find('@');
        string clean;
        for (size_t j = 0; j < at; j++) {
            if (e[i][j] == '+') break;
            if (e[i][j] != '.') clean += e[i][j];
        }
        unique.insert(clean + e[i].substr(at));
    }
    cout << unique.size() << "\n";

    return 0;
}

